#!/usr/bin/python3
import os,sys,subprocess,shutil,json
from pathlib import Path
args=sys.argv[1:];bare=args[2:] if args[:1]==['-c'] else args
base=Path('/home/elias/.cache/am/r50zwz6b/tmp')
if bare[:2]==['worktree','add']:
 dest,ref=bare[-2:]
 env={k:v for k,v in os.environ.items() if k not in ['GIT_OBJECT_DIRECTORY','GIT_ALTERNATE_OBJECT_DIRECTORIES','GIT_INDEX_FILE']}
 source='/home/elias/dev/js-uiux-compat-ingress'
 with (base/'git-adapter.log').open('a') as f:
  for cmd,cwd in [(['/usr/bin/git','clone','--quiet','--shared','--no-checkout',source,dest],source),(['/usr/bin/git','-C',dest,'checkout','--quiet','--detach',ref],source),(['npm','ci'],dest+'/modules/ui-web')]:
   f.write(json.dumps({'command':cmd,'cwd':cwd})+'\n');f.flush()
   result=subprocess.run(cmd,cwd=cwd,env=env,stdout=f,stderr=subprocess.STDOUT)
   if result.returncode:sys.exit(result.returncode)
 sys.exit(0)
if bare[:2]==['worktree','remove']:
 dest=Path(bare[-1]).resolve()
 if not dest.is_relative_to(base):raise RuntimeError('refuse outside own temporary root')
 shutil.rmtree(dest);sys.exit(0)
os.execv('/usr/bin/git',['/usr/bin/git',*args])

